import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { API } from "../utils";

import { motion } from "framer-motion";
import "animate.css";

import { FaTooth, FaPills } from "react-icons/fa";
import "../styles/main.css";

const AddObat = () => {
  const [nama_obat, setNama] = useState("");
  const [definisi, setDefinisi] = useState("");
  const [efek_samping, setEfekSamping] = useState("");
  const [harga, setHarga] = useState("");
  const navigate = useNavigate();
  const [msg, setMsg] = useState("");

  const saveObat = async (e) => {
    e.preventDefault();
    try {
      const token = localStorage.getItem("accessToken");
      if (!token) {
        setMsg("Silakan login terlebih dahulu.");
        return;
      }
      await API.post(
        "/add-obat",
        {
          nama_obat,
          definisi,
          efek_samping,
          harga: parseInt(harga),
        },
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
          withCredentials: true,
        },
      );

      navigate("/obat");
    } catch (error) {
      console.error("Error saving obat data:", error);
      setMsg("Gagal menyimpan data obat.");
    }
  };

  return (
    <motion.div
      className="add-obat-container animate__animated animate__fadeIn"
      initial={{ opacity: 0, y: 50 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.7 }}
    >
      <h1 className="title-custom">
        <FaTooth size={32} color="#0277bd" /> Tambah Data Obat <FaPills size={32} color="#0277bd" />
      </h1>

      {msg && <div className="notification-custom">{msg}</div>}

      <form onSubmit={saveObat}>
        <div className="field">
          <label>Nama Obat</label>
          <input
            type="text"
            className="input-custom"
            value={nama_obat}
            onChange={(e) => setNama(e.target.value)}
            required
            placeholder="Masukkan nama obat"
          />
        </div>

        <div className="field">
          <label>Definisi</label>
          <input
            type="text"
            className="input-custom"
            value={definisi}
            onChange={(e) => setDefinisi(e.target.value)}
            required
            placeholder="Deskripsi obat"
          />
        </div>

        <div className="field">
          <label>Efek Samping</label>
          <input
            type="text"
            className="input-custom"
            value={efek_samping}
            onChange={(e) => setEfekSamping(e.target.value)}
            required
            placeholder="Efek samping jika ada"
          />
        </div>

        <div className="field">
          <label>Harga</label>
          <input
            type="number"
            className="input-custom"
            value={harga}
            onChange={(e) => setHarga(e.target.value)}
            required
            placeholder="Masukkan harga obat"
            min={0}
          />
        </div>

        <motion.button
          type="submit"
          className="button-custom"
          whileHover={{ scale: 1.05, backgroundColor: "#015f8b" }}
          whileTap={{ scale: 0.95 }}
          style={{ width: "100%", padding: "12px", marginTop: "1rem" }}
        >
          Simpan Data Obat
        </motion.button>
      </form>
    </motion.div>
  );
};

export default AddObat;
